    84	function saveWaypoint(transactionID: string, index: string, waypoint: RecentWaypoint | null, isDraft = false) {
    85	    Onyx.merge(`${isDraft ? ONYXKEYS.COLLECTION.TRANSACTION_DRAFT : ONYXKEYS.COLLECTION.TRANSACTION}${transactionID}`, {
    86	        comment: {
    87	            waypoints: {
    88	                [`waypoint${index}`]: waypoint,
    89	            },
    90	            customUnit: {
    91	                quantity: null,
    92	            },
    93	        },
    94	        // We want to reset the amount only for draft transactions (when creating the expense).
    95	        // When modifying an existing transaction, the amount will be updated on the actual IOU update operation.
    96	        ...(isDraft && {amount: CONST.IOU.DEFAULT_AMOUNT}),
    97	        // Empty out errors when we're saving a new waypoint as this indicates the user is updating their input
    98	        errorFields: {
    99	            route: null,
   100	        },
   101	
   102	        // Clear the existing route so that we don't show an old route
   103	        routes: {
   104	            route0: {
   105	                // Clear the existing distance to recalculate next time
   106	                distance: null,
   107	                geometry: {
   108	                    coordinates: null,
   109	                },
   110	            },
   111	        },
   112	    });
   113	
   114	    // You can save offline waypoints without verifying the address (we will geocode it on the backend)
   115	    // We're going to prevent saving those addresses in the recent waypoints though since they could be invalid addresses
   116	    // However, in the backend once we verify the address, we will save the waypoint in the recent waypoints NVP
   117	    if (!lodashHas(waypoint, 'lat') || !lodashHas(waypoint, 'lng')) {
   118	        return;
   119	    }
   120	
   121	    // If current location is used, we would want to avoid saving it as a recent waypoint. This prevents the 'Your Location'
   122	    // text from showing up in the address search suggestions
   123	    if (isEqual(waypoint?.address, CONST.YOUR_LOCATION_TEXT)) {
   124	        return;
   125	    }
   126	    const recentWaypointAlreadyExists = recentWaypoints.find((recentWaypoint) => recentWaypoint?.address === waypoint?.address);
   127	    if (!recentWaypointAlreadyExists && waypoint !== null) {
   128	        const clonedWaypoints = lodashClone(recentWaypoints);
   129	        clonedWaypoints.unshift(waypoint);
   130	        Onyx.merge(ONYXKEYS.NVP_RECENT_WAYPOINTS, clonedWaypoints.slice(0, CONST.RECENT_WAYPOINTS_NUMBER));
   131	    }
   132	}
